def build():
    areas = [{"id": aid, "name": name, "order": i + 1} for i, (aid, name) in enumerate(AREAS)]
    topics = []
    for tid, area, name, desc, includes, refs in TOPICS:
        topics.append({
            "id": tid, "area": area, "name": name, "description": desc,
            "includes": includes,
            "refs": [{"label": lbl, "url": url} for lbl, url in refs],
        })
    assignments = {}
    for pid in sorted(A):
        prim, sec, key, conf = A[pid]
        assignments[pid] = {
            "primary": prim, "secondary": list(sec), "key_idea": key,
            "confidence": {"h": "high", "m": "medium"}[conf],
        }
    tax = {"areas": areas, "topics": topics, "assignments": assignments}
    with open(OUT, "w", encoding="utf-8") as fh:
        json.dump(tax, fh, ensure_ascii=False, indent=1)
        fh.write("\n")
    print(f"wrote {OUT}: {len(areas)} areas, {len(topics)} topics, {len(assignments)} assignments")


if __name__ == "__main__":
    build()
